public class Lichtschalter {

    enum Zustand { AUS, EINGESCHALTET, DEFEKT }

    public static void main(String[] args) {
        Zustand lampe = Zustand.AUS;

        switch (lampe) {
            case AUS -> System.out.println("Die Lampe ist aus");
            case EINGESCHALTET -> System.out.println("Die Lampe leuchtet");
            case DEFEKT -> System.out.println("Lampe ersetzen!");
        }
    }
}

